// 
//     /// Command operations
//     fn commands(&self) -> &dyn CommandsAPI;
// 
//     /// Language features
//     fn languages(&self) -> &dyn LanguagesAPI;
// 
//     /// Debug operations
//     fn debug(&self) -> &dyn DebugAPI;
// 
//     /// Source control management
//     fn scm(&self) -> &dyn SCMAPI;
// 
//     /// Terminal operations
//     fn terminal(&self) -> &dyn TerminalAPI;
// 
//     /// Environment operations
//     fn env(&self) -> &dyn EnvironmentAPI;
// }
// 
// /// Extension activation context
// pub trait ExtensionContext {
//     fn extension_uri(&self) -> &Uri;
//     fn extension_path(&self) -> &Path;
//     fn subscriptions(&mut self) -> Vec<Box<dyn Disposable>>;
//     fn workspace_state(&self) -> &dyn Memento;
//     fn global_state(&self) -> &dyn Memento;
//     fn as_absolute_path(&self, relative_path: &Path) -> PathBuf;
//     fn storage_uri(&self) -> Option<&Uri>;
//     fn global_storage_uri(&self) -> &Uri;
// }
// ```
