//         let spine = Arc::clone(&self.spine);
//         let local = Arc::clone(&self.local);
//         let uri = uri.clone();
// 
//         async move {
//             // Try local first
//             match local.read_file(&uri).await {
//                 Ok(data) => return Ok(data),
