// 
// 	// Replaces MountainConfigurationService
// 	configuration: "local" | "cloud" | "user-preference";
// 
// 	// Replaces MountainWorkspaceService
// 	workspace: "github" | "gitlab" | "local-fs";
// 
// 	// Replaces MountainCommandService
// 	commands: "local-only" | "remote-proxy";
// }
// 
