// 
// # Application Load Balancer
// resource "aws_lb" "app" {
//   name               = "codeeditorland-alb-${var.environment}"
//   internal           = false
//   load_balancer_type = "application"
//   security_groups    = [aws_security_group.alb.id]
//   subnets           = var.public_subnet_ids
// 
//   enable_deletion_protection = false
// 
//   tags = {
//     Name        = "CodeEditorLand ALB"
//     Environment = var.environment
//   }
// }
// 
// resource "aws_lb_target_group" "app" {
//   name     = "codeeditorland-tg-${var.environment}"
//   port     = 3000
//   protocol = "HTTP"
//   vpc_id   = var.vpc_id
// 
//   health_check {
//     enabled             = true
//     path                = "/health"
//     port                = "traffic-port"
//     healthy_threshold   = 2
//     unhealthy_threshold = 3
//     timeout             = 5
//     interval            = 30
//     matcher             = "200"
