// 
// ### Docker Configuration
// 
// ```dockerfile
// # Dockerfile
// FROM node:20-alpine AS builder
// 
// WORKDIR /app
// 
// # Copy package files
// COPY package*.json ./
// RUN npm ci --only=production
// 
// # Copy source code
// COPY . .
// 
// # Build the application
// RUN npm run build:standalone
// 
// # Production image
// FROM node:20-alpine
// 
// WORKDIR /app
// 
// # Copy built application
// COPY --from=builder /app/dist/standalone ./dist/standalone
// COPY --from=builder /app/node_modules ./node_modules
// COPY package*.json ./
// 
// # Expose port
// EXPOSE 3000
// 
// # Health check
// HEALTHCHECK --interval=30s --timeout=3s --start-period=5s --retries=3 \
// 	CMD node healthcheck.js || exit 1
// 
// # Start application
// CMD ["node", "dist/standalone/server.js"]
// ```
// 
// ### Docker Compose for Local Development
// 
// ```yaml
// # docker-compose.yml
// version: "3.8"
// 
// services:
//     app:
//         build:
//             context: .
//             dockerfile: Dockerfile
//         ports:
//             - "3000:3000"
//         environment:
//             - NODE_ENV=production
//             - DATABASE_URL=postgresql://user:password@postgres:5432/codeeditorland
//             - REDIS_URL=redis://redis:6379
//         depends_on:
//             - postgres
//             - redis
//         volumes:
//             - ./dist/standalone:/app/dist/standalone
// 
//     postgres:
//         image: postgres:15-alpine
//         environment:
//             POSTGRES_DB: codeeditorland
//             POSTGRES_USER: user
//             POSTGRES_PASSWORD: password
//         ports:
//             - "5432:5432"
//         volumes:
