// ### 2. Netlify
// 
// ### Deployment Configuration
// 
// ```toml
// # netlify.toml
// [build]
// command = "npm run build:standalone"
// publish = "dist/standalone"
// 
// [[headers]]
// for = "/assets/*"
// [headers.values]
// Cache-Control = "public, max-age=31536000, immutable"
// 
// [[headers]]
// for = "/*"
// [headers.values]
// X-Frame-Options = "DENY"
// X-Content-Type-Options = "nosniff"
// X-XSS-Protection = "1; mode=block"
// 
// [[redirects]]
// from = "/api/*"
// to = "https://api.codeeditorland.com/api/:splat"
// status = 200
// force = true
// 
// [dev]
// command = "npm run dev"
// port = 3000
// ```
