// 	return router;
// }
// ```
// 
// ### Readiness Probe
// 
// **Endpoint:** `/ready`
// 
// Returns 200 when the service is ready to accept traffic.
// 
// ```rust
// pub async fn readiness_check(
//     transports: web::Data<Vec<Arc<dyn TransportStrategy>>>,
// ) -> impl Responder {
//     let all_ready = transports.iter().all(|t| t.is_connected());
// 
//     if all_ready {
//         HttpResponse::Ok().json({"ready": true})
//     } else {
//         HttpResponse::ServiceUnavailable().json({
//             "ready": false,
//             "message": "Not all transports are connected"
//         })
//     }
// }
// ```
// 
// ### Liveness Probe
// 
// **Endpoint:** `/live`
// 
// Returns 200 when the service is alive (not deadlocked).
