// ## Configuration
// 
// ### Client Configuration
// 
// ```typescript
// export interface GrpcClientConfig {
// 	host: string;
// 	port: number;
// 
// 	// Connection settings
// 	timeout?: number;
// 	keepAliveTime?: number;
// 	keepAliveTimeout?: number;
// 	maxCallAttempts?: number;
// 
// 	// TLS settings
// 	ssl?: boolean;
// 	sslRootCertPath?: string;
// 	sslCertPath?: string;
// 	sslKeyPath?: string;
// 
// 	// Channel pool settings
// 	maxChannels?: number;
// 	maxConcurrentStreams?: number;
// 
// 	// Interceptors
// 	interceptors?: GrpcInterceptor[];
// }
// 
// export const defaultGrpcConfig: GrpcClientConfig = {
// 	host: "localhost",
// 	port: 50051,
// 	timeout: 30000,
// 	keepAliveTime: 300000,
// 	keepAliveTimeout: 5000,
// 	maxCallAttempts: 3,
// 	ssl: false,
// 	maxChannels: 10,
// 	maxConcurrentStreams: 100,
// };
// ```
// 
