// 			this.pool.delete(key);
// 			return client;
// 		}
// 
// 		if (this.currentSize >= this.maxSize) {
// 			throw new Error("Connection pool exhausted");
// 		}
// 
// 		const client = new GrpcClient(address);
// 		this.currentSize++;
// 		return client;
// 	}
// 
