// 			this.pool.set(address, client);
// 		} else {
// 			client.disconnect().catch(console.error);
// 			this.currentSize--;
// 		}
// 	}
// }
// ```
// 
// #### 2. Message Compression
// 
// ```protobuf
// message Message {
//   string id = 1;
//   MessageType type = 2;
//   bytes payload = 3 [(grpc.field_encoding) = GZIP];
// }
// ```
// 
// #### 3. Keep-Alive Settings
// 
// ```typescript
// const client = new GrpcClient("localhost", 50051, {
// 	keepAliveTime: 300000, // 5 minutes
// 	keepAliveTimeout: 5000, // 5 seconds
// 	keepAlivePermitWithoutCalls: true,
// });
// ```
