//     if (n <= 1) return 1;
//     return n * factorial(n - 1);
// }
// 
// EMSCRIPTEN_KEEPALIVE
// void process_array(uint8_t* data, int32_t length) {
//     for (int i = 0; i < length; i++) {
//         data[i] = data[i] + 1;
//     }
// }
// 
// EMSCRIPTEN_KEEPALIVE
// const char* get_message() {
//     return "Hello from C WASM!";
// }
// ```
