// ## Extension Development
// 
// ### Getting Started
// 
// #### 1. Initialize Extension
// 
// ```bash
// # Create extension project
// npm init @codeeditorland/extension my-extension
// cd my-extension
// 
// # Install dependencies
// npm install
// 
// # Start development
// npm run dev
// ```
// 
// #### 2. Extension Entry Point
// 
// ```typescript
// import * as cel from "codeeditorland";
// import * as vscode from "vscode";
// 
// export function activate(context: vscode.ExtensionContext) {
// 	// Register command
// 	const disposable = vscode.commands.registerCommand(
// 		"myExtension.hello",
// 		() => {
// 			vscode.window.showInformationMessage("Hello from My Extension!");
// 		},
// 	);
// 
// 	// Use CodeEditorLand native API
// 	const fileSystem = cel.getActiveAPI<cel.Filesystem>("filesystem");
// 	const files = await fileSystem.listFiles(".");
// 	console.log("Files:", files);
// 
// 	context.subscriptions.push(disposable);
// }
// 
// export function deactivate() {
// 	console.log("Extension deactivated");
// }
// ```
// 
