//     }
// 
//     pub async fn get(&self) -> T {
//         let mut service = self.service.write().await;
//         if service.is_none() {
//             *service = Some((self.factory)());
//         }
//         service.as_ref().unwrap().clone()
//     }
// }
// ```
// 
// #### 2. Connection Pooling
// 
